{
  "findings": [
    {
      "check_id": "CKV_AWS_355",
      "title": "Ensure no IAM policies documents allow '*' as a statement's resource for restrictable actions",
      "resource": "aws_iam_policy.privesc-ssmStartSession-policy",
      "severity": "MEDIUM",
      "explanation": "The IAM policy allows '*' as a resource for actions that can be restricted, such as 'ssm:StartSession' and 'ssm:TerminateSession', potentially allowing privilege escalation on any resource."
    },
    {
      "check_id": "CKV_AWS_290",
      "title": "Ensure IAM policies does not allow write access without constraints",
      "resource": "aws_iam_policy.privesc-ssmStartSession-policy",
      "severity": "MEDIUM",
      "explanation": "The policy allows write actions like 'ssm:StartSession', 'ssm:TerminateSession', and 'ssm:ResumeSession' without resource constraints, which could lead to unauthorized access or modifications."
    }
  ],
  "patched_code": ```hcl
resource "aws_iam_policy" "privesc-ssmStartSession-policy" {
  name        = "privesc-ssmStartSession-policy"
  path        = "/"
  description = "Allows privesc via targeted ssm"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action = [
          "ec2:DescribeInstances",
          "ssm:DescribeSessions",
          "ssm:GetConnectionStatus",
          "ssm:DescribeInstanceProperties"
        ]
        Resource = "*"
      },
      {
        Effect   = "Allow"
        Action = [
          "ssm:StartSession",
          "ssm:TerminateSession",
          "ssm:ResumeSession"
        ]
        Resource = "arn:aws:ec2:*:*:instance/*"
      },
    ]
  })
}
```,
  "fix_summary": "Constrained the 'ssm:StartSession', 'ssm:TerminateSession', and 'ssm:ResumeSession' actions to specific instance resources, while keeping 'ec2:DescribeInstances' and other read-only actions on '*'. This reduces the risk of privilege escalation on arbitrary resources."
}
